function parseCSV(text){
 const rows=[];let row=[],field='',quoted=false,closed=false;
 const pushRow=()=>{row.push(field);rows.push(row);row=[];field='';closed=false};
 for(let i=0;i<text.length;i++){
  const ch=text[i];
  if(quoted){if(ch==='"'){if(text[i+1]==='"'){field+='"';i++}else{quoted=false;closed=true}}else field+=ch;continue}
  if(ch===','){row.push(field);field='';closed=false}else if(ch==='\n'||ch==='\r'){if(ch==='\r'&&text[i+1]==='\n')i++;pushRow()}
  else if(ch==='"'){if(field!==''||closed)throw Error('CSVの引用符位置が不正です');quoted=true}
  else{if(closed)throw Error('CSVの閉じ引用符の後に文字があります');field+=ch}
 }
 if(quoted)throw Error('CSVの引用符が閉じていません');if(field!==''||row.length||closed)pushRow();return rows;
}
