 if(!plain(w)||w.version!==1||!Array.isArray(w.projects)||!w.projects.length||w.projects.length>200||typeof w.activeId!=='string'||!plain(w.colors))throw Error('現場一覧の保存形式が不正です');
 const palette={};for(const k of ['S','L','R']){if(typeof w.colors[k]!=='string'||!/^#[0-9a-f]{6}$/i.test(w.colors[k]))throw Error('色の保存形式が不正です');palette[k]=w.colors[k]}
 const seen=new Set();let found=false;const ps=w.projects.map(p=>{if(!plain(p)||typeof p.id!=='string'||! /^[A-Za-z0-9-]{1,100}$/.test(p.id)||seen.has(p.id)||typeof p.name!=='string'||p.name.length>100||!Number.isFinite(p.updatedAt)||p.updatedAt<0)throw Error('現場一覧を確認してください');seen.add(p.id);const selected=p.id===w.activeId;if(selected)found=true;return{id:p.id,name:p.name,updatedAt:p.updatedAt,data:selected?null:rawDraft(p.data)}});if(!found)throw Error('現在の現場が一覧にありません');
